    "pythia1b_c4_a100_s42": {
        "label": "C4 Domain",
        "canaries": ["token_entropy", "ece"],
        "downstreams": ["mauve", "distinct_1", "distinct_2", "distinct_3"],
    },
    "opt1b_wiki_a100_s42": {
        "label": "OPT-1.3B",
        "canaries": ["token_entropy", "ece"],
        "downstreams": ["perplexity", "distinct_1", "distinct_2", "distinct_3"],
    },
    "pythia14b_wiki_a100_s42": {
        "label": "Scale 1.4B",
        "canaries": ["token_entropy", "ece"],
        "downstreams": ["perplexity", "distinct_1", "distinct_2", "distinct_3"],
    },
}

N_PERM = 5000
XCORR_MAX_LAG = 5
GRANGER_MAX_LAG = 1
ALPHA = 0.05

METHOD_NAMES = ["naive_pearson", "differenced_xcorr", "threshold_onset",
                "toda_yamamoto", "permutation_granger"]


class NumpyEncoder(json.JSONEncoder):
    def default(self, obj):
