        return super().default(obj)


def assemble_metrics(exp_dir):
    all_path = os.path.join(exp_dir, "all_metrics.json")
    if os.path.exists(all_path):
        with open(all_path) as f:
            return json.load(f)
    metrics = []
    gen_idx = 0
    while True:
        mpath = os.path.join(exp_dir, f"gen_{gen_idx}", "metrics.json")
        if not os.path.exists(mpath):
            break
        with open(mpath) as f:
            m = json.load(f)
        m["generation"] = gen_idx
        metrics.append(m)
        gen_idx += 1
    return sorted(metrics, key=lambda x: x["generation"]) if metrics else None


def run_methods(c, d, cn, dn):
    results = {}
    results["naive_pearson"] = naive_pearson(c, d, cn, dn, max_lag=XCORR_MAX_LAG)
    results["differenced_xcorr"] = diff_xcorr(c, d, cn, dn, max_lag=XCORR_MAX_LAG)
    results["threshold_onset"] = threshold_lead(c, d, cn, dn)
    results["toda_yamamoto"] = toda_yamamoto(c, d, cn, dn)
    results["permutation_granger"] = perm_granger(c, d, cn, dn,
                                                   max_lag=GRANGER_MAX_LAG,
                                                   n_perm=N_PERM)
    return results


def get_p(res):
    """Extract p-value, handling p=0.0 correctly (0.0 is valid, not None)."""
    p = res.get("p_value")
    if p is not None:
        return p
    p = res.get("p_raw")
    if p is not None:
        return p
    return None


def is_sig_raw(res):
    """Check significance: use p_value if available, else use 'significant' field."""
    p = get_p(res)
    if p is not None:
        return bool(p < ALPHA)
    sig = res.get("significant")
    if sig is not None:
        return bool(sig)
    return False


def analyze_one(exp_name, exp_cfg):
    exp_dir = os.path.join(GENERALIZE_DIR, exp_name)
    metrics_list = assemble_metrics(exp_dir)
    if metrics_list is None:
        print(f"  {exp_name}: no metrics found", flush=True)
        return None

    n_gens = len(metrics_list)
    print(f"  {exp_name}: {n_gens} generations", flush=True)

    canaries = exp_cfg["canaries"]
    downstreams = exp_cfg["downstreams"]
    pairs = list(product(canaries, downstreams))

    pair_results = {}
    all_p_method = {m: [] for m in METHOD_NAMES}
    all_p_method_keys = {m: [] for m in METHOD_NAMES}
    all_p_pooled = []
    all_p_pooled_keys = []

    for cn, dn in pairs:
        pk = f"{cn}->{dn}"
        c = extract(metrics_list, cn)
        d = extract(metrics_list, dn)
        res = run_methods(c, d, cn, dn)
        pair_results[pk] = res

        for mn in METHOD_NAMES:
            p = get_p(res[mn])
            if p is not None:
                all_p_method[mn].append(p)
                all_p_method_keys[mn].append(pk)
                all_p_pooled.append(p)
                all_p_pooled_keys.append((pk, mn))

    # FDR per-method
    fdr_permethod = {}
    for mn in METHOD_NAMES:
        ps = all_p_method[mn]
        keys = all_p_method_keys[mn]
        if ps:
            _, fdr_ps, _, _ = multipletests(ps, alpha=ALPHA, method="fdr_bh")
            fdr_permethod[mn] = dict(zip(keys, [float(x) for x in fdr_ps]))
        else:
            fdr_permethod[mn] = {}

    # FDR pooled
    fdr_pooled = {}
    if all_p_pooled:
        _, fdr_ps_pooled, _, _ = multipletests(all_p_pooled, alpha=ALPHA, method="fdr_bh")
        for i, (pk, mn) in enumerate(all_p_pooled_keys):
            fdr_pooled[(pk, mn)] = float(fdr_ps_pooled[i])

    n_pairs = len(pair_results)
    summary = {
        "experiment": exp_name,
        "label": exp_cfg["label"],
        "n_generations": n_gens,
        "params": {
            "n_perm": N_PERM, "xcorr_max_lag": XCORR_MAX_LAG,
            "granger_max_lag": GRANGER_MAX_LAG, "alpha": ALPHA,
        },
        "pairs": {},
        "method_summary": {},
    }

    for pk in pair_results:
        pair_detail = {}
        for mn in METHOD_NAMES:
            res = pair_results[pk][mn]
            p_raw = get_p(res)
            p_fdr_pm = fdr_permethod[mn].get(pk)
            p_fdr_pool = fdr_pooled.get((pk, mn))

            sig_raw = is_sig_raw(res)
            sig_fdr_pm = bool(p_fdr_pm is not None and p_fdr_pm < ALPHA)
            sig_fdr_pool = bool(p_fdr_pool is not None and p_fdr_pool < ALPHA)

            # For threshold_onset (no p-value), use raw significant for all scopes
            if p_raw is None:
                sig_fdr_pm = sig_raw
                sig_fdr_pool = sig_raw

            pair_detail[mn] = {
                "raw": {k: v for k, v in res.items()},
                "p_raw": round(p_raw, 6) if p_raw is not None else None,
                "p_fdr_permethod": round(p_fdr_pm, 6) if p_fdr_pm is not None else None,
                "p_fdr_pooled": round(p_fdr_pool, 6) if p_fdr_pool is not None else None,
                "sig_raw": sig_raw,
                "sig_fdr_permethod": sig_fdr_pm,
                "sig_fdr_pooled": sig_fdr_pool,
            }
        summary["pairs"][pk] = pair_detail

    # Per-method summary counts
    for mn in METHOD_NAMES:
        raw_sig = sum(1 for pk in pair_results
                      if summary["pairs"][pk][mn]["sig_raw"])
        fdr_pm_sig = sum(1 for pk in pair_results
                         if summary["pairs"][pk][mn]["sig_fdr_permethod"])
        fdr_pool_sig = sum(1 for pk in pair_results
                           if summary["pairs"][pk][mn]["sig_fdr_pooled"])
        summary["method_summary"][mn] = {
            "raw_sig": f"{raw_sig}/{n_pairs}",
            "fdr_permethod_sig": f"{fdr_pm_sig}/{n_pairs}",
            "fdr_pooled_sig": f"{fdr_pool_sig}/{n_pairs}",
        }

    # K>=3 and K>=4 counts
    for k_thresh in [3, 4]:
        label = f"K>={k_thresh}"
        raw_cnt = fdr_pm_cnt = fdr_pool_cnt = 0
        for pk in pair_results:
            raw_votes = sum(1 for mn in METHOD_NAMES
                           if summary["pairs"][pk][mn]["sig_raw"])
            fdr_pm_votes = sum(1 for mn in METHOD_NAMES
                               if summary["pairs"][pk][mn]["sig_fdr_permethod"])
            fdr_pool_votes = sum(1 for mn in METHOD_NAMES
                                 if summary["pairs"][pk][mn]["sig_fdr_pooled"])
            if raw_votes >= k_thresh:
                raw_cnt += 1
            if fdr_pm_votes >= k_thresh:
                fdr_pm_cnt += 1
            if fdr_pool_votes >= k_thresh:
                fdr_pool_cnt += 1
        summary["method_summary"][label] = {
            "raw_sig": f"{raw_cnt}/{n_pairs}",
            "fdr_permethod_sig": f"{fdr_pm_cnt}/{n_pairs}",
            "fdr_pooled_sig": f"{fdr_pool_cnt}/{n_pairs}",
        }

    return summary


def main():
    all_results = {}
    for exp_name, exp_cfg in EXPERIMENTS.items():
        print(f"\nAnalyzing {exp_name} ({exp_cfg['label']})...", flush=True)
        result = analyze_one(exp_name, exp_cfg)
        if result:
            all_results[exp_name] = result
            out_dir = os.path.join(GENERALIZE_DIR, exp_name, "analysis")
            os.makedirs(out_dir, exist_ok=True)
            out_path = os.path.join(out_dir, "unified_5method.json")
            with open(out_path, "w") as f:
                json.dump(result, f, indent=2, cls=NumpyEncoder)
            print(f"  Saved: {out_path}", flush=True)

    combined_path = os.path.join(GENERALIZE_DIR, "analysis", "unified_generalize_all.json")
    os.makedirs(os.path.dirname(combined_path), exist_ok=True)
    with open(combined_path, "w") as f:
        json.dump(all_results, f, indent=2, cls=NumpyEncoder)
    print(f"\nCombined saved: {combined_path}", flush=True)

    # === SUMMARY TABLE ===
    print("\n" + "=" * 90)
    print("SUMMARY TABLE")
    print("=" * 90)
    hdr = f"{'Experiment':<16} {'Method/K':<22} {'Raw_p<.05':>10} {'FDR_pm':>10} {'FDR_pool':>10}"
    print(hdr)
    print("-" * 90)

    for exp_name in EXPERIMENTS:
        if exp_name not in all_results:
            continue
        r = all_results[exp_name]
        label = r["label"]
        for key in METHOD_NAMES + ["K>=3", "K>=4"]:
            ms = r["method_summary"][key]
            print(f"{label:<16} {key:<22} {ms['raw_sig']:>10} "
                  f"{ms['fdr_permethod_sig']:>10} {ms['fdr_pooled_sig']:>10}")
        print()

    # === ALL METHODS PER-PAIR RAW P-VALUES ===
    print("\n" + "=" * 100)
    print("ALL METHODS PER-PAIR RAW P-VALUES (threshold uses sig field, not p)")
    print("=" * 100)
    for exp_name in EXPERIMENTS:
        if exp_name not in all_results:
            continue
        r = all_results[exp_name]
        print(f"\n{r['label']} ({exp_name}):")
        hdr = f"  {'Pair':<30}"
        for mn in METHOD_NAMES:
            short = mn[:10]
            hdr += f" {short:>12}"
        print(hdr)
        print("  " + "-" * (30 + 13 * len(METHOD_NAMES)))
        for pk, pd in r["pairs"].items():
            line = f"  {pk:<30}"
            for mn in METHOD_NAMES:
                p = pd[mn]["p_raw"]
                sig = pd[mn]["sig_raw"]
                if p is not None:
                    sig_mark = "*" if sig else " "
                    line += f" {p:>11.4f}{sig_mark}"
                else:
                    # threshold_onset: show sig status
                    if mn == "threshold_onset":
                        line += f" {'SIG' if sig else 'n.s.':>12}"
                    else:
                        line += f" {'N/A':>12}"
            print(line)

    # === PER-PAIR PG DETAIL ===
    print("\n" + "=" * 100)
    print("PER-PAIR PERMUTATION GRANGER DETAIL")
    print("=" * 100)
    for exp_name in EXPERIMENTS:
        if exp_name not in all_results:
            continue
        r = all_results[exp_name]
        print(f"\n{r['label']} ({exp_name}):")
        for pk, pd in r["pairs"].items():
            pg = pd["permutation_granger"]
            p_raw = pg["p_raw"]
            p_pm = pg["p_fdr_permethod"]
            p_pool = pg["p_fdr_pooled"]
            s_r = "*" if pg["sig_raw"] else " "
            s_pm = "*" if pg["sig_fdr_permethod"] else " "
            s_pool = "*" if pg["sig_fdr_pooled"] else " "
            pr = f"{p_raw:.4f}" if p_raw is not None else "N/A"
            ppm = f"{p_pm:.4f}" if p_pm is not None else "N/A"
            pp = f"{p_pool:.4f}" if p_pool is not None else "N/A"
            print(f"  {pk:<30} raw={pr}{s_r}  fdr_pm={ppm}{s_pm}  fdr_pool={pp}{s_pool}")

    # === PER-PAIR K VOTES ===
    print("\n" + "=" * 100)
    print("PER-PAIR K VOTES (raw p / FDR_pm / FDR_pool)")
    print("=" * 100)
    for exp_name in EXPERIMENTS:
        if exp_name not in all_results:
            continue
        r = all_results[exp_name]
        print(f"\n{r['label']} ({exp_name}):")
        print(f"  {'Pair':<30} {'K_raw':>6} {'K_fdr_pm':>9} {'K_fdr_pool':>11}")
        print("  " + "-" * 60)
        for pk, pd in r["pairs"].items():
            k_raw = sum(1 for mn in METHOD_NAMES if pd[mn]["sig_raw"])
            k_pm = sum(1 for mn in METHOD_NAMES if pd[mn]["sig_fdr_permethod"])
            k_pool = sum(1 for mn in METHOD_NAMES if pd[mn]["sig_fdr_pooled"])
            print(f"  {pk:<30} {k_raw:>4}/5 {k_pm:>7}/5 {k_pool:>9}/5")

    print(f"\nTimestamp: {datetime.now().isoformat()}")


if __name__ == "__main__":
    main()
